if (event.data.type === "session.deleted") {
  console.log("Record deletion", event.data.id);
} else if (event.data.type === "session.status_idled") {
  try {
    const session = await client.beta.sessions.retrieve(
      event.data.id
    );
    console.log(session.id, session.status);
  } catch (error) {
    if (error instanceof Anthropic.NotFoundError) {
      console.log("Resource unavailable", event.data.id);
    } else {
      throw error;
    }
  }
}
